\label{P:2.1} Let $M^n$ be a submanifold of an almost contact metric manifold $\widetilde M^{2m+1}$ with $\mathfrak{\xi}\in\Gamma(TM^n)$. Then $M^n$ is pointwise slant if and only if 
\begin{align}\label{charac} T^2=\cos^2\theta\left(-I+\eta\otimes\mathfrak{\xi}\right),\end{align}
where $\theta$ is the slant function and  $I$ denotes the identity map on $TM^{n}$.

From \eqref{sasaki} and \eqref{gauss}, we have
\begin{align}
 \label{cs1}
 A_\mathfrak{\xi}X=TX,\quad
 \nabla^\perp_X\xi=-FX,
 \end{align}
 for any $X\in\Gamma(TM)$. Taking the inner product in \eqref{cs1} with $Y\in\Gamma(TM)$, we get
 \begin{align}
 \label{cs2}
 g(h(X, Y), \mathfrak{\xi})=g(TX, Y).
 \end{align}
 From \eqref{cs2}, we find $\cos^2\theta\;g(X, Y)=0$ via polarization identity. Since, the metric $g$ is Riemannian,  we obtain $\theta=\frac{\pi}{2}$. The converse is trivial.

\label{L:4.2} Let $M^n=N_T\times_{f_1}N_\perp\times_{f_2}N_\theta$ be a $CRS$ bi-warped product in a cosymplectic manifold $\widetilde M^{2m+1}$. Then we have
\begin{enumerate}
\item[(i)] $g(h(X, Y), \varphi Z)=0=g(h(X, Y),FV)$;
\item [(ii)] $g(h(X, Z), \varphi W)=-\varphi X(\ln f_1)\,g(Z, W)$;
\item[(iii)] $g(h(X,U), FV)=-\varphi X(\ln f_2)\,g(U, V)-X(\ln f_2)\,g(U, TV)$.
\end{enumerate}
for $X,Y\in \Gamma({\mathfrak{D}^{T}})$, $Z,W\in \Gamma({\mathfrak{D}}^\perp)$ and  $U,V\in \Gamma({\mathfrak{D}}^\theta)$.

For any $X, Y\in \Gamma({\mathfrak{D}^{T}})$ and $Z\in \Gamma({\mathfrak{D}}^\perp)$, we find
\begin{align*}
g(h(X, Y), \varphi Z)\, &=g(\widetilde\nabla_XY, \varphi Z)=-g(\widetilde\nabla_X\varphi Y, Z)=-g(\nabla_X\varphi Y, Z).
\end{align*}
Using the fact that $N_T$ is totally geodesic in $M^n$ (see Remark \ref{R:3.1}) with the orthogonality of vector fields, we find $g(h(X, Y), \varphi Z)=0$, which is the first equality of (i). Similarly, we have the second equality of (i). 
For (ii), we have
\begin{align*}
g(h(X, Z), \varphi W)\, &=g(\widetilde\nabla_ZX, \varphi W)=g((\widetilde\nabla_Z\varphi)X, W)-g((\widetilde\nabla_Z\varphi X, W).
\end{align*}
Using \eqref{cosy}, Remark \ref{R:3.2}, and \eqref{warped} with the orthogonality of vector fields, we get (ii). Similarly, we obtain (iii).

\label{L:4.3} Let $M^n=N_T\times_{f_1}N_\perp\times_{f_2}N_\theta$ be a $CRS$ bi-warped product in a cosymplectic manifold $\widetilde M^{2m+1}$. Then \begin{align}\label{4.9}
g(h(X, Z),FV)=g(h(X, V), \varphi Z)=0,\end{align}
for any $X\in \Gamma({\mathfrak{D}^{T}})$, $Z\in \Gamma({\mathfrak{D}}^\perp)$ and $V\in \Gamma({\mathfrak{D}}^\theta)$.

 For any $X\in \Gamma({\mathfrak{D}^{T}})$,\,\, $Z\in \Gamma({\mathfrak{D}}^\perp)$ and $V\in \Gamma({\mathfrak{D}}^\theta)$, we have
\begin{equation*} \begin{aligned}
g(h(X, Z), FV)\;&=g(\widetilde{\nabla}_ZX-\nabla_ZX, \varphi V-TV)\\&=g((\widetilde{\nabla}_{Z}\varphi)X, V) -g(\widetilde\nabla_{Z}\varphi X, V)-X(\ln f_1)\,g(Z, TV).
\end{aligned}\end{equation*}
Then we find the first equality of \eqref{4.9} from \eqref{cosy}, \e{warped} and the orthogonality of vector fields. 
For the second equality, first we have
 \begin{align*}
g(h(X, V), \varphi Z)&=g(\widetilde{\nabla}_VX, \varphi Z)=-g(\widetilde\nabla_V\varphi X, Z)=-\varphi X(\ln f_2)\,g(Z, V)=0,
\end{align*}
which gives the second equality of \eqref{4.9}.

\label{T:5.1} Let $M=N_T\times_{f_1}N^{n_{1}}_\perp\times_{f_2}N^{n_{2}}_\theta$ be a $CRS$ bi-warped product in a $(2m+1)$-dimensional cosymplectic manifold $\widetilde M^{2m+1}$. Then
\begin{enumerate}
\item[(i)] The squared norm of the second fundamental from satisfies 
\begin{equation}\label{5.1}
\|h\|^2\geq 2n_1\|\nabla(\ln f_1)\|^2+2n_2(1+2\cot^2\theta)\,\|\nabla(\ln f_2)\|^2, 
\end{equation}
where $\nabla(\ln f_1)$ and $\nabla(\ln f_2)$ are the gradients of $\ln f_{1}$ and $\ln f_{2}$, respectively.
\item[(ii)] If the equality sign holds in \eqref{5.1}, then $N_T$ is totally geodesic in $\widetilde M^{2m+1}$ and $N^{n_{1}}_\perp$ and $N^{n_{2}}_\theta$ are totally umbilical submanifolds of $\widetilde M^{2m+1}$. Moreover, $M$ is a ${\mathfrak{D}}^\perp\oplus{\mathfrak{D}}^\theta$-mixed totally geodesic submanifold but neither ${\mathfrak{D}^{T}}\oplus {\mathfrak{D}}^\perp$-mixed totally geodesic nor ${\mathfrak{D}^{T}}\oplus {\mathfrak{D}}^\theta$-mixed totally geodesic.
\end{enumerate}

 From \eqref{funda}, we have
\begin{align*}
\|h\|^2=\sum_{i,j=1}^ng(h(e_i, e_j), h(e_i, e_j)) =\sum_{r=n+1}^{2m+1}\sum_{i,j=1}^ng(h(e_i, e_j), e_r)^2.\end{align*}
By using \eqref{tan-nor}, the above equation takes the form
\begin{align*}
\|h\|^2&=\sum_{r=n+1}^{2m+1}\sum_{i,j=1}^{2p+1}g(h(e_i, e_j), e_r)^2+\sum_{r=n+1}^{2m+1}\sum_{i,j=1}^{n_1}g(h(\bar e_i, \bar e_j), e_r)^2\\
&+\sum_{r=n+1}^{2m+1}\sum_{i,j=1}^{n_2}g(h(e_i^{*}, e_j^{*}), e_r)^2+2\sum_{r=n+1}^{2m+1}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_1}g(h(e_i, \bar e_j), e_r)^2\\
&+2\sum_{r=n+1}^{2m+1}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_2}g(h(e_i, e_j^{*}), e_r)^2+2\sum_{r=n+1}^{2m+1}\sum_{i=1}^{n_1}\sum_{j=1}^{n_2}g(h(\bar e_i,  e_j^{*}), e_r)^2.
\end{align*}
Again, we derive from \eqref{tan-nor} that
\begin{align}
\|h\|^2&=\sum_{r=1}^{n_1}\sum_{i,j=1}^{2p+1}g(h(e_i, e_j), \varphi \bar e_r)^2+\sum_{r=1}^{n_2}\sum_{i,j=1}^{2p+1}g(h(e_i, e_j), \hat{e}_r)^2\notag\\
&+\sum_{r=1}^{2m+1-n-n_1-n_2}\sum_{i,j=1}^{2p+1}g(h(e_i, e_j), \widetilde e_r)^2+\sum_{r=1}^{n_1}\sum_{i,j=1}^{n_1}g(h(\bar e_i, \bar e_j), \varphi \bar e_r)^2
\notag\\
&+\sum_{r=1}^{n_2}\sum_{i,j=1}^{n_1}g(h(\bar e_i, \bar e_j), \hat{e}_r)^2+\sum_{r=1}^{2m+1-n-n_1-n_2}\sum_{i,j=1}^{n_1}g(h(\bar e_i, \bar e_j), \widetilde {e}_r)^2\notag\\
&+\sum_{r=1}^{n_1}\sum_{i,j=1}^{n_2}g(h(e_i^{*}, e_j^{*}), \varphi \bar e_r)^2+\sum_{r=1}^{n_2}\sum_{i,j=1}^{n_2}g(h(e_i^{*}, e_j^{*}), \hat{e}_r)^2
\notag\\ \label{5.2}
&+2\sum_{r=1}^{n_1}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_1}g(h(e_i, \bar e_j), \varphi \bar e_r)^2+2\sum_{r=1}^{n_2}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_1}g(h(e_i, \bar e_j), \hat e_r)^2 
\\
&+2\sum_{r=1}^{2m+1-n-n_1-n_2}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_1}g(h(e_i, \bar e_j), \widetilde e_r)^2+2\sum_{r=1}^{n_2}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_2}g(h(e_i, e_j^{*}), \hat e_r)^2\notag
\\& \notag
+2\sum_{r=1}^{n_1}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_2}g(h(e_i, e_j^{*}), \varphi\bar e_r)^2+2\sum_{r=1}^{2m+1-n-n_1-n_2}\sum_{i=1}^{2p+1}\sum_{j=1}^{n_2}g(h(e_i, e_j^{*}), \widetilde e_r)^2\notag\\
&+2\sum_{r=1}^{n_1}\sum_{i=1}^{n_1}\sum_{j=1}^{n_2}g(h(\bar e_i,  e_j^{*}), \varphi \bar e_r)^2+2\sum_{r=1}^{n_2}\sum_{i=1}^{n_1}\sum_{j=1}^{n_2}g(h(\bar e_i,  e_j^{*}), \hat e_r)^2
\notag\\
&+2\sum_{r=1}^{2m+1-n-n_1-n_2}\sum_{i=1}^{n_1}\sum_{j=1}^{n_2}g(h(\bar e_i,  e_j^{*}), \widetilde e_r)^2.\notag
\end{align}
Let us omit the  positive 3rd, 6th, 9th, 12th, 15th and 18th terms of $\mu$-components in the right hand side of \eqref{5.2}. Since we couldn't find any relations for the 4th, 5th, 7th, 8th, 16th and 17th terms, we also omit these positive terms and using Lemma \ref{L:4.2}(i), the 1st and 2nd terms vanish identically. Similarly, the 11th and 13th terms vanish according to Lemma \ref{L:4.3}. Hence, with the remaining 10th and 14th terms, the above expression becomes
\begin{equation}\begin{aligned}\label{5.3}
\|h\|^2\geq\; & 2\sum_{r=1}^{n_1}\sum_{i=1}^{p}\sum_{j=1}^{n_1}g(h(e_i, \bar e_j), \varphi \bar e_r)^2+2\sum_{r=1}^{n_1}\sum_{i=1}^{p}\sum_{j=1}^{n_1}g(h(\varphi e_i, \bar e_j), \varphi \bar e_r)^2\\ 
&+2\sum_{r=1}^{n_1}\sum_{j=1}^{n_1}g(h(\mathfrak{\xi}, \bar e_j), \varphi \bar e_r)^2+2\sum_{r=1}^{n_2}\sum_{i=1}^{p}\sum_{j=1}^{n_2}g(h(e_i, e_j^{*}), \hat e_r)^2
\\& +2\sum_{r=1}^{n_2}\sum_{i=1}^{p}\sum_{j=1}^{n_2}g(h(\varphi e_i, e_j^{*}), \hat e_r)^2+2\sum_{r=1}^{n_2}\sum_{j=1}^{n_2}g(h((\mathfrak{\xi}, e_j^{*}), \hat e_r)^2.
\end{aligned}\end{equation}

From Lemma \ref{L:4.1}, the 3rd and 6th terms of \e{5.3} are identical zero. Then, by using (ii)-(iii) of Lemma \ref{L:4.2} and  \eqref{4.2}-\eqref{4.8} with orthonormality of vector fields, we find
\begin{align}\label{5.4}
\|h\|^2\; & \geq2n_1\sum_{i=1}^{p}(e_i\ln f_1)^2+2n_1\sum_{i=1}^{p}(\varphi e_i\ln f_1)^2+2n_2(\csc^2\theta+\cot^2\theta)\sum_{i=1}^{p}(\varphi e_i\ln f_2)^2\notag\\
&+2n_2(\csc^2\theta+\cot^2\theta)\sum_{i=1}^{p}(e_i\ln f_2)^2.
\end{align}
Since  $\mathfrak{\xi}(\ln f_1)=\mathfrak{\xi}(\ln f_2)=0$ from Lemma \ref{L:4.1}, the above relation becomes
\begin{equation}\begin{aligned}\label{5.5}
\|h\|^2&\geq2n_1\sum_{i=1}^{2p+1}(e_i\ln f_1)^2+2n_2(\csc^2\theta+\cot^2\theta)\sum_{i=1}^{2p+1}(e_i\ln f_2).
\end{aligned}\end{equation}
So,  we find the inequality given in statement (i) via the definition of gradient. 

For the equality, it follows from the omitted $\mu$-components terms in \eqref{5.2} that\begin{align}\label{eq1}
h(TM, TM)\perp\mu
\end{align}
Also, from the omitted 4th and 5th terms in \eqref{5.2}, we have
\begin{align}\label{eq2}
h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\perp)\perp \varphi{\mathfrak{D}}^\perp,\,\,\,\,\,h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\perp)\perp F{\mathfrak{D}}^\theta.
\end{align}
Then  we obtain from \eqref{eq1} and \eqref{eq2} that
\begin{align}\label{eq3}
h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\perp)=\{0\}.
\end{align}
From the omitted 7th and 8th terms in the right hand side of \eqref{5.2}, we get
\begin{align}\label{eq5}
h({\mathfrak{D}}^\theta, {\mathfrak{D}}^\theta)\perp \varphi{\mathfrak{D}}^\perp,\,\,\,\,\,h({\mathfrak{D}}^\theta, {\mathfrak{D}}^\theta)\perp F{\mathfrak{D}}^\theta.
\end{align}
Thus  we conclude from \eqref{eq1} and \eqref{eq5} that
\begin{align}\label{eq6}
h({\mathfrak{D}}^\theta, {\mathfrak{D}}^\theta)=\{0\}.
\end{align}

Similarly, from the omitted 16th and 17th terms in the right hand side of  \eqref{5.2}, we arrive at
\begin{align}\label{eq7}
h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\theta)\perp\varphi{\mathfrak{D}}^\perp,\,\,\,\,\,h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\theta)\perp F{\mathfrak{D}}^\theta.
\end{align}
From \eqref{eq1} and \eqref{eq7}, we find
\begin{align}\label{eq8}
h({\mathfrak{D}}^\perp, {\mathfrak{D}}^\theta)=\{0\}.
\end{align}

On the other hand, we find from the vanishing 1st and 2nd terms of \e{5.2} that
\begin{align}\label{eq9}
h({\mathfrak{D}^{T}}, {\mathfrak{D}^{T}})\perp\varphi{\mathfrak{D}}^\perp,\,\,\,\,\,h({\mathfrak{D}^{T}},\, {\mathfrak{D}^{T}})\perp F{\mathfrak{D}}^\theta.
\end{align}
Thus,  we derive from \eqref{eq1} and \eqref{eq9}, that
\begin{align}\label{eq10}
h({\mathfrak{D}^{T}}, {\mathfrak{D}^{T}})=\{0\}.
\end{align}
And, from the vanishing 11th term of \eqref{5.2} and \eqref{eq1}, we get
\begin{align}\label{eq11}
h({\mathfrak{D}^{T}}, {\mathfrak{D}}^\perp)\subset \varphi{\mathfrak{D}}^\perp.
\end{align}
Similarly, from the vanishing 13th term in \eqref{5.2} with \eqref{eq1}, we find
\begin{align}\label{eq12}
h({\mathfrak{D}^{T}}, {\mathfrak{D}}^\theta)\subset F{\mathfrak{D}}^\theta.
\end{align}
Since $N_T$ is totally geodesic in $M$ (see Remark \ref{R:3.1}), using this fact with \eqref{eq3}, \eqref{eq6} and \eqref{eq10}. Again, from \eqref{eq8}, \eqref{eq11} and \eqref{eq12} with Remark \ref{R:3.1}, we conclude that $N_\perp$ and $N_\theta$ are totally umbilical in $\widetilde M$, while; using all conditions with  \eqref{eq8} $M$ is a ${\mathfrak{D}}^\perp\oplus {\mathfrak{D}}^\theta$-mixed totally geodesic submanifold of $\widetilde M$ but not ${\mathfrak{D}^{T}}\oplus {\mathfrak{D}}^\perp$ and ${\mathfrak{D}^{T}}\oplus {\mathfrak{D}}^\theta$-mixed totally geodesic.

 By applying the same methods given in \cite{CD} and in \cite{HM}, we have the following extension of Corollary \ref{C:5.1} to  contact multiply CR-warped product  $N_T\times_{f_1}N_1^{n_{1}}\times\cdots\times_{f_k}N_k^{n_{k}}$ of cosymplectic manifolds $\widetilde M^{2m+1}$, where $N_T$ is invariant and $N_{1}^{1},\ldots,N_{k}^{n_{k}}$ are anti-invariant submanifolds of $\widetilde M^{2m+1}$.

\begin{theorem}\label{T:5.2} Let $M=N_T\times_{f_1}N_1^{n_{1}}\times\cdots\times_{f_k}N_k^{n_{k}}$ be a contact multiply CR-warped product in a cosymplectic manifold $\widetilde M^{2m+1}$. Then
\begin{align}\label{5.17}
\|h\|^2\geq2\sum_{i=1}^{k}n_i \|\nabla(\ln f_i)\|^2.
\end{align}

The equality sign in \eqref{5.17} holds identically if and only if the following three conditions hold:
\begin{enumerate}
\item[(a)] $N_T$ is a totally geodesic submanifold of $\widetilde M^{2m+1}$.
\item[(b)] $N_i\; (i=1,\cdots, k)$ are totally umbilical submanifolds of $\widetilde M^{2m+1}$.
\item[(c)] $_{f_1}N_1\times\cdots\times_{f_k}N_k$ is mixed totally geodesic in $\widetilde M^{2m+1}$
\end{enumerate}
\end{theorem}

