\rm{Let ${\mathbb{R}}^{19}$ denotes the Cartesian space with the Cartesian coordinates $(x_1,\,y_1,\,\cdots,\,x_9,\, y_9,\, z)$. Consider the contact metric structure $(\varphi,\xi,\eta,g)$  on ${\mathbb{R}}^{19}$, where $g$ is the standard Euclidean metric and $\varphi,\xi,\eta$ are defined by
\begin{equation}\label{7.1}
\xi=\frac{\partial}{\partial z},\; \eta=dz,\;  \varphi\left(\frac{\partial}{\partial x_i}\right)=-\frac{\partial}{\partial y_i},\;  \varphi\left(\frac{\partial}{\partial y_i}\right)=\frac{\partial}{\partial x_i},\; \varphi \left(\frac{\partial}{\partial z}\right)=0, 
\end{equation} 
for $i=1,\ldots,9$. Also,  we have $d\eta=d\varphi =0$ and $\widetilde \nabla \varphi=\widetilde \nabla \xi=0$. Hence, ${\mathbb{R}}^{19}$ is a cosymplectic manifold.


Let $M^{7}$ be the submanifold of ${\mathbb{R}}^{19}$ given by 
\begin{equation}\begin{aligned}\label{7.2}
\psi(u,\, v,\, w,\, s,\, t,\, r,\, z)=\; &\Big(u\cos w,\, v\cos w,\, u\cos s,\, v\cos s,\,u\sin w,\, v\sin w,\, \\
&\hskip-1.1in  u\sin s,\, v\sin s, u\cos t,\, v\cos t,\, u\cos r,\,v\cos r,\, u\sin t,\, v\sin t,\, u\sin r,\,\\
&\hskip-.7in   v\sin r,\,k(r-t),\, -k(r+t), z\Big), \;\; u\neq 0,\; v\neq 0,\; k\in\mathbb{R}-\left\lbrace 0 \right\rbrace.
\end{aligned}\end{equation}
Then the tangent bundle $TM^{7}$ is spanned by the following coordinate vector fields with respect to $u,\, v,\, w,\, s,\, t,\, r,\, z$, respectively.
\begin{align}\notag
&W_1=\cos w\,\frac{\partial}{\partial x_1}+\cos s\,\frac{\partial}{\partial x_2}+\sin w\,\frac{\partial}{\partial x_3}+\sin s\,\frac{\partial}{\partial x_4}+\cos t\,\frac{\partial}{\partial x_5}+\cos r\,\frac{\partial}{\partial x_6}
\\&\notag\hskip.3in +\sin t\,\frac{\partial}{\partial x_7}+\sin r\,\frac{\partial}{\partial x_8},\\
&\notag W_2=\cos w\,\frac{\partial}{\partial y_1}+\cos s\,\frac{\partial}{\partial y_2}+\sin w\,\frac{\partial}{\partial y_3}+\sin s\,\frac{\partial}{\partial y_4}+\cos t\,\frac{\partial}{\partial y_5} +\cos r\,\frac{\partial}{\partial y_6}\\&\notag\hskip.3in+\sin t\,\frac{\partial}{\partial y_7}+\sin r\,\frac{\partial}{\partial y_8},\\
&\label{7.3} W_3=-u\sin w\,\frac{\partial}{\partial x_1}-v\sin w\,\frac{\partial}{\partial y_1}+u\cos w\,\frac{\partial}{\partial x_3}+v\cos w\,\frac{\partial}{\partial y_3},\\
 &\notag W_4=-u\sin s\,\frac{\partial}{\partial x_2}-v\sin s\,\frac{\partial}{\partial y_2}+u\cos s\,\frac{\partial}{\partial x_4}+v\cos s\,\frac{\partial}{\partial y_4},\\
&\notag W_5=-u\sin t\,\frac{\partial}{\partial x_5}-v\sin t\,\frac{\partial}{\partial y_5}+u\cos t\,\frac{\partial}{\partial x_7}+v\cos t\,\frac{\partial}{\partial y_7}
 -k\frac{\partial}{\partial x_9}-k\frac{\partial}{\partial y_9},\\
&\notag W_6=-u\sin r\,\frac{\partial}{\partial x_6}-v\sin r\,\frac{\partial}{\partial y_6}+u\cos r\,\frac{\partial}{\partial x_8}+v\cos r\,\frac{\partial}{\partial y_8}
+k\frac{\partial}{\partial x_9}-k\frac{\partial}{\partial y_9},
\\&\notag W_7=\frac{\partial}{\partial z}.
\end{align}
Then we find $\varphi W_7=0$ and
\begin{align}\notag
&\varphi W_1=-\cos w\,\frac{\partial}{\partial y_1}-\cos s\,\frac{\partial}{\partial y_2}-\sin w\,\frac{\partial}{\partial y_3}-\sin s\,\frac{\partial}{\partial y_4}-\cos t\,\frac{\partial}{\partial y_5}
\\&\notag \hskip.45in -\cos r\,\frac{\partial}{\partial y_6}-\sin t\,\frac{\partial}{\partial y_7}-\sin r\,\frac{\partial}{\partial y_8},
\\&\notag  \varphi W_2=\cos w\,\frac{\partial}{\partial x_1}+\cos s\,\frac{\partial}{\partial x_2}+\sin w\,\frac{\partial}{\partial x_3}+\sin s\,\frac{\partial}{\partial x_4}+\cos t\,\frac{\partial}{\partial x_5}
\\&\notag \hskip.45in +\cos r\,\frac{\partial}{\partial x_6}+\sin t\,\frac{\partial}{\partial x_7}+\sin r\,\frac{\partial}{\partial x_8},
 \\&\label{7.4} \varphi W_3=-v\sin w\,\frac{\partial}{\partial x_1}+u\sin w\,\frac{\partial}{\partial y_1}+v\cos w\,\frac{\partial}{\partial x_3}-u\cos w\,\frac{\partial}{\partial y_3},
\\ &\notag  \varphi W_4=-v\sin s\,\frac{\partial}{\partial x_2}+ u\sin s\,\frac{\partial}{\partial y_2}+v\cos s\,\frac{\partial}{\partial x_4}-u\cos s\,\frac{\partial}{\partial y_4},
\\&\notag \varphi W_5=-v\sin t\frac{\partial}{\partial x_5}+u\sin t\,\frac{\partial}{\partial y_5}+v\cos t\frac{\partial}{\partial x_7}-u\cos t\frac{\partial}{\partial y_7}-k\frac{\partial}{\partial x_9}
 +k\frac{\partial}{\partial y_9}, \\
&\notag \varphi W_6=-v\sin r\,\frac{\partial}{\partial x_6}+u\sin r\,\frac{\partial}{\partial y_6}+v\cos r\,\frac{\partial}{\partial x_8}-u\cos r\,\frac{\partial}{\partial y_8}-k\frac{\partial}{\partial x_9}  -k\frac{\partial}{\partial y_9}.
\end{align}
Clearly, ${\mathfrak{D}^{T}}=\rm{Span}\{W_1,W_2,W_{7}\}$ is an invariant distribution. Since both $\varphi W_3$ and $\varphi W_4$ are orthogonal to $TM^{7}$, ${\mathfrak{D}}^{\perp}=\rm{Span}\{W_3, W_4\}$ is an anti-invariant distribution. Further, it is direct to show that ${\mathfrak{D}^{\theta}}=\rm{Span}\{W_5,W_6\}$ is a pointwise slant distribution with slant function $\theta=\arccos (\frac{2k^2}{u^2+v^2+2k^2})$. 

Obviously, ${\mathfrak{D}^{T}},\, {\mathfrak{D}}^{\perp}$ and ${\mathfrak{D}}^{\theta}$ are integrable distributions on $M$.  If we denote the integral manifolds of ${\mathfrak{D}^{T}},\;{\mathfrak{D}}^\perp$ and ${\mathfrak{D}^{T}}^{\theta}$ by $N_T,\, N_\perp$ and $N_\theta$, respectively, then the induced metric tensor $g$ of $M= N_T\times_{f_1}N_\perp\times_{f_2} N_\theta$ is given by
\begin{equation}\begin{aligned}\label{7.5}
&g=g_{N_T}+f^2_1g_{N_\perp}+f^2_2g_{N_\theta},\\
&g_{N_T}=4(du^2+dv^2)+dz^2,\;\; g_{N_{\perp}}=dw^2+ds^2,\;\; g_{N_{\theta}}=dt^2+dr^2,
\\& f_{1}=\sqrt{u^{2}+ v^{2}}, \;\; f_2=\sqrt{u^2+v^2+2k^2}.
\end{aligned}\end{equation}
Hence, $M^{7}$ is a $CRS$ bi-warped product in ${\mathbb{R}}^{19}$ which satisfy $\xi f_{1}=\xi f_{2}=0$. 

Let $\widetilde \nabla$ denote the Riemannian connection on ${\mathbb{R}}^{19}$.
Since $h(W_{i},W_{j})$ is the normal component of $\widetilde \nabla_{W_{i}}W_{j}$, it follows easily from \e{7.3} that
\begin{align}\label{7.6} &h(\mathfrak{D}^{T}, \mathfrak{D}^{T})=h(\mathfrak{D}^{\perp}, \mathfrak{D}^{\perp})=h(\mathfrak{D}^{\perp}, \mathfrak{D}^{\theta})=h(\mathfrak{D}^{\theta}, \mathfrak{D}^{\theta})=\{0\},
\\&\label{7.6}h(\xi, \mathfrak{D}^{\perp})=h(\xi, \mathfrak{D}^{\theta})=\{0\},\quad \xi=\frac{\partial}{\partial z}.
\end{align}

  Furthermore, we find from \e{7.3} and \e{7.4} that 
\begin{align*}
